{"version":3,"file":"NowRecordListConnected.jsdbx","sources":["../../../usr/src/app/node_modules/.pnpm/@servicenow+react-components@0.1.8_react-dom@18.2.0_react@18.2.0__react@18.2.0/node_modules/@servicenow/react-components/dist/NowRecordListConnected.js"],"sourcesContent":["import React, { useRef, useCallback } from 'react';
import '@servicenow/now-record-list-connected' assert { external: 'uxasset' };
import { useServiceNowEvent } from './utils/useServiceNowEvents.js';
import { setProperties } from './utils/setProperties.js';
import { ServiceNowEvents } from './utils/events.js';
import { useHTMLAttributes } from './utils/useHTMLAttributes.js';
import './hooks/useRecord.js';
import { useOpenRecordAPI } from './hooks/useOpenRecordAPI.js';
import './ux_globals_loader/data_providers/userSessionProvider.js';
import './ux_globals_loader/data_providers/deviceInfoProvider.js';
import './ux_globals_loader/data_providers/sysPropsProvider.js';
import './ux_globals_loader/data_providers/hardcodedProvider.js';
import './ux_globals_loader/data_providers/computedProvider.js';

const NowRecordListConnected = props => {
 const { table, listTitle, limit, view, columns, hideHeader, hideQuickEdit, hideInlineEditing, hideRowSelector, onNewActionClicked, onRowClicked, onSelectedRecordCountUpdated, onQueryUpdated, onDataFetchRequested, onDataFetchSucceeded, onRefreshRequested, ...rest } = props;
 const elementRef = useRef(null);
 const openRecordApi = useOpenRecordAPI();
 const onItemSelectedHandler = useCallback((e) => {
 /**
 * The legacy create-new action dispatches ITEM_SELECTED and not CREATE_NEW_RECORD
 * the contract for ITEM_SELECTED is very different
 * from the CREATE_NEW_RECORD event
 * this is trying to ensure if and when we want to swap out the event
 * the actionHandler API doesn't change
 */
 const { detail } = e;
 const { payload, ...detailRest } = detail;
 if (payload?.row?.sys_id?.value !== '-1')
 return;
 const createNewRecordPayload = {
 table: payload.table,
 sysId: payload.row.sys_id.value,
 query: payload.additional_data.query
 };
 const newEvent = new CustomEvent(ServiceNowEvents.LISTS.CREATE_NEW_RECORD, {
 detail: {
 ...detailRest,
 payload: createNewRecordPayload
 }
 });
 if (onNewActionClicked) {
 onNewActionClicked(newEvent);
 }
 else {
 // Default: open record in new tab
 openRecordApi.openInNewTab({
 table: createNewRecordPayload.table,
 sysId: createNewRecordPayload.sysId,
 params: {
 query: createNewRecordPayload.query
 }
 });
 }
 }, [onNewActionClicked, openRecordApi]);
 const onRowClickedHandler = useCallback((e) => {
 if (onRowClicked) {
 onRowClicked(e);
 }
 else {
 // Default: open record in new tab
 const { detail } = e;
 const { payload } = detail;
 openRecordApi.openInNewTab({
 table: payload.table,
 sysId: payload.sys_id
 });
 }
 }, [onRowClicked, openRecordApi]);
 // Attach event listeners
 useServiceNowEvent(elementRef, ServiceNowEvents.LISTS.ITEM_SELECTED, onItemSelectedHandler);
 useServiceNowEvent(elementRef, ServiceNowEvents.LISTS.ROW_CLICKED, onRowClickedHandler);
 useServiceNowEvent(elementRef, ServiceNowEvents.LISTS.SELECTED_RECORD_COUNT_UPDATED, onSelectedRecordCountUpdated);
 useServiceNowEvent(elementRef, ServiceNowEvents.LISTS.QUERY_UPDATED, onQueryUpdated);
 useServiceNowEvent(elementRef, ServiceNowEvents.LISTS.DATA_FETCH_REQUESTED, onDataFetchRequested);
 useServiceNowEvent(elementRef, ServiceNowEvents.LISTS.DATA_FETCH_SUCCEEDED, onDataFetchSucceeded);
 useServiceNowEvent(elementRef, ServiceNowEvents.LISTS.REFRESH_REQUESTED, onRefreshRequested);
 // Set properties
 setProperties(elementRef, {
 table,
 listTitle,
 limit,
 view,
 columns,
 hideHeader,
 hideQuickEdit,
 hideInlineEditing,
 hideRowSelector,
 workspaceConfigId: '7b24ceae5304130084acddeeff7b12a3' //use legacy actions until UXF client actions or UI interactions are supported
 });
 const restProps = useHTMLAttributes(elementRef, rest);
 return React.createElement("now-record-list-connected", { ref: elementRef, ...restProps });
};

export { NowRecordListConnected };
